function mergeBaseIntoBranch(): string {
  const branch = resolveBranch();
  const inProgress = gitRun("rev-parse", "-q", "--verify", "MERGE_HEAD");
  if (inProgress.code === 0) {
    mcpFail(
      "A merge is already in progress on this branch. Resolve the conflicted files and call " +
      "commit_and_push to close it, or discard the merge before merging another base in.",
    );
  }
  const worktree = gitRun("status", "--porcelain");
  if (worktree.code) mcpFail(worktree.stderr || worktree.stdout);
  if (worktree.stdout.trim()) {
    mcpFail("Cannot merge the base branch into a branch with uncommitted changes. Commit them with commit_and_push first.");
  }

  const base = mergeBaseBranch();
  if (!base) mcpFail(...) // can't happen: mergeBaseBranch throws or returns non-empty
  if (base === branch) mcpFail(`The base branch is '${base}', which is the branch this run is on; there is nothing to bring in.`);

  const remoteRef = `refs/remotes/origin/${base}`;
  const fetch = gitRun("fetch", "origin", `refs/heads/${base}:${remoteRef}`);
  if (fetch.code) mcpFail(`Cannot fetch base branch '${base}': ${fetch.stderr || fetch.stdout}`);
  const baseSha = gitRun("rev-parse", remoteRef);
  if (baseSha.code) mcpFail(`Cannot resolve base branch '${base}': ...`);

  const already = gitRun("merge-base", "--is-ancestor", remoteRef, "HEAD");
  if (already.code === 0) {
    logOp("merge_base_into_branch", { branch, base, status: "up_to_date", base_sha });
    return JSON.stringify({ status: "up_to_date", base, base_sha: baseSha });
  }

  const message = `Merge base branch '${base}' (${sha.slice(0,7)}) into '${branch}'`;
  const merge = gitRun("merge", "--no-ff", "--no-commit", remoteRef); // then commit ourselves with our message
```

