```ts
function mergeBaseBranch(): string {
  const num = nodeNumber();
  // A pull request run is on a pull request's branch, and the base that pull request
  // aims at is the one base that branch must take in. Reading it from the pull
  // request rather than resolving the issue tree is the same rule `create_pr`
  // states -- a stacked pull request's base is its parent's branch -- applied to the
  // node this run is actually on.
  if (isPrRun() && num !== undefined) {
    const pr = ghJsonOrThrow<{ baseRefName?: string }>("pr", "view", String(num), "--repo", REPO, "--json", "baseRefName");
    const base = (pr?.baseRefName ?? "").trim();
    if (base) return base;
  }
  const fromTree = stackedPrBase(REPO) ?? getBaseBranch();
  if (fromTree) return fromTree;
  // Empty means "the repository's default branch", which `gh pr create` resolves on
  // its own and a merge cannot.
  const repo = ghJsonOrThrow<{ defaultBranchRef?: { name?: string } }>("repo", "view", REPO, "--json", "defaultBranchRef");
  const name = (repo?.defaultBranchRef?.name ?? "").trim();
  if (!name) mcpFail("Cannot tell which branch this work is based on: ...");
  return name;
}
```

