```ts
/**
 * The merge an unfinished `merge_base_into_branch` left behind, if any.
 *
 * `MERGE_HEAD` is git's own record that a commit would have two parents, and the
 * unmerged entries in the index are what is still to be decided. They have to be
 * counted BEFORE `git add -A`, because staging a conflicted path is how git is told
 * the conflict is resolved: `add -A` here would mark every marker file resolved and
 * commit the markers into the branch.
 */
function unfinishedMerge(): { head: string; unresolved: string[]; description: string } | undefined {
  const head = gitRun("rev-parse", "-q", "--verify", "MERGE_HEAD");
  if (head.code !== 0) return undefined;
  const unmerged = gitRun("diff", "--name-only", "--diff-filter=U");
  const unresolved = unmerged.code === 0 ? unmerged.stdout.split("\n").map((l) => l.trim()).filter(Boolean) : [];
  return { head: head.stdout.trim(), unresolved, description: mergeMessage() };
}
```

For description: read MERGE_MSG.

```ts
/**
 * git's own record of what this merge is bringing in, as its first line.
 *
 * `git merge -m` puts the message there, so a merge started by
 * `merge_base_into_branch` leaves `Merge base branch 'main' (abc1234) into ...`;
 * git's own default is `Merge branch 'main' of ...`. Read rather than recomposed,
 * because the base a conflicted merge came from is decided when it starts, and the
 * branch configured as the base may have moved since.
 */
function mergeMessage(): string {
  const dir = gitRun("rev-parse", "--git-dir");
  if (dir.code) return "";
  const path = join(dir.stdout.trim(), "MERGE_MSG");
  try {
    return readFileSync(path, "utf8").split("\n").map(l => l.trim()).find(l => l && !l.startsWith("#")) ?? "";
  } catch { return ""; }
}
```

