Now, the code:

```ts
/**
 * `git merge` — the one git mutation an agent needs that had no route, and the gap
 * that made the shell guard's refusal untrue.
 *
 * #264: a pull request whose base moved ahead could not be brought up to date by any
 * tool. `sync_branch` fast-forwards THIS branch from its own remote, which is the
 * other question; `create_pr` and `merge_pr` refuse while the branch is behind. The
 * run that hit it built the merge commit by hand out of `commit-tree` and
 * `update-ref`, because a refusal naming the github tools and a tool set with no
 * merge in it left nothing else — and that merge reached no ops log, so the only
 * record of it was the transcript.
 *
 * One node, one branch, one direction. The base is the branch this run's pull
 * request aims at (see `baseBranchForMerge`), and it comes INTO the checked-out
 * branch. Nothing is pushed anywhere else, no child or sibling branch is touched, and
 * nothing cascades: each node takes the base in when it needs it.
 *
 * Conflicts are left in the worktree, markers and all, and this commits nothing. Which
 * side wins is a judgement about the code — including a `package.json` version, where
 * either answer is plausible and a machine picking one silently rolls a release back.
 */
function mergeBaseIntoBranch(): string {
  try {
    return mergeBaseIntoBranchOrThrow();
  } catch (error) {
    logOp("merge_base_into_branch", { status: "failed", reason: (error as Error).message });
    throw error;
  }
}

function mergeBaseIntoBranchOrThrow(): string {
  const branch = resolveBranch();
  if (unfinishedMerge()) {
    mcpFail(
      "A merge is already in progress on this branch. Resolve its conflicts and call commit_and_push to " +
      "close it before merging another base in.",
    );
  }
  const worktree = gitRun("status", "--porcelain");
  if (worktree.code) mcpFail(worktree.stderr || worktree.stdout);
  if (worktree.stdout.trim()) {
    mcpFail("Cannot merge the base branch into a branch with uncommitted changes. Call commit_and_push first.");
  }

  const base = baseBranchForMerge();
  if (base === branch) {
    mcpFail(`'${base}' is both this run's branch and its base, so there is nothing to bring in.`);
  }
  const remoteRef = `refs/remotes/origin/${base}`;
  const fetch = gitRun("fetch", "origin", `refs/heads/${base}:${remoteRef}`);
  if (fetch.code) mcpFail(`Cannot fetch base branch '${base}': ${fetch.stderr || fetch.stdout}`);
  const resolved = gitRun("rev-parse", remoteRef);
  if (resolved.code) mcpFail(`Cannot resolve base branch '${base}': ${resolved.stderr || resolved.stdout}`);
  const baseSha = resolved.stdout.trim();

  const ancestor = gitRun("merge-base", "--is-ancestor", remoteRef, "HEAD");
  if (ancestor.code === 0) {
    logOp("merge_base_into_branch", { branch, base, status: "up_to_date", base_sha: baseSha });
    return JSON.stringify({ status: "up_to_date", base, base_sha: baseSha, branch });
  }
  if (ancestor.code !== 1) mcpFail(`Cannot compare '${branch}' with '${base}': ${ancestor.stderr || ancestor.stdout}`);

  const merge = gitRun("merge", "--no-ff", "-m", `Merge base branch '${base}' (${baseSha.slice(0, 12)}) into '${branch}'`, remoteRef);
  const conflicts = gitRun("diff", "--name-only", "--diff-filter=U");
  const files = conflicts.stdout.split("\n").map((line) => line.trim()).filter(Boolean);
  if (files.length > 0) {
    // Not committed, and deliberately not `merge --abort`: the markers are the work.
    logOp("merge_base_into_branch", { branch, base, status: "conflicts", base_sha: baseSha, files });
    return JSON.stringify({
      status: "conflicts",
      base,
      base_sha: baseSha,
      files,
      note: "The conflicts are in the worktree with their markers, and nothing was committed. Resolve them, then call commit_and_push to close the merge.",
    });
  }
  if (merge.code) mcpFail(`Merging '${base}' into '${branch}' failed: ${merge.stderr || merge.stdout}`);

  const head = gitRun("rev-parse", "HEAD");
  if (head.code) mcpFail(`Cannot resolve HEAD after the merge: ${head.stderr || head.stdout}`);
  const commit = head.stdout.trim();
  pushBranch(branch);
  logOp("merge_base_into_branch", { branch, base, status: "merged", base_sha: baseSha, commit });
  return JSON.stringify({ status: "merged", base, base_sha: baseSha, commit, branch });
}
